internal object DuaBrxDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("जागोदानब्ला", "गासिबो बाख्नायनाया अल्लाहनि थाखाय, जाय जोंफोरखौ जिउ होखांनायनि उनाव जिउ होदोंमोन, आरो बिथांनिनो फैफिन्नायनि।", "उनदुनायनिफ्राय उन्दुयोब्ला, अल्लाहखौ बाखनायनो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ सिरिनाय समाव फरायदोंमोन-साननि जागायनाया उन समनि बाखनायनाय आरो गोसोखांनायजों।"),
        "dua_leaving_home" to DuaText("न'निफ्राय ओंखारबोयोब्ला", "अल्लाहनि मुंजों; आं अल्लाहनि सायाव फोथायो। अल्लाहनि अनगा जेबो गोहो आरो गोहो गैया।", "न'निफ्राय ओंखारबोयोब्ला, अल्लाहनि रैखाथिनि थाखाय।", "फेरेशताफोरा बुङोः'नों लामा दिन्थिजायो, नोंखौ जोथोन लानाय जायो आरो नोंखौ रैखाथि होनाय जायो', आरो शैतनआ खारलाङो।"),
        "dua_anxiety_distress" to DuaText("उसुखुथु आरो दुखुनिफ्राय आराम।", "ऐ अल्लाह, आं नोंखौ जिंगा आरो दुखुनिफ्राय, लोरबांथि आरो आलसियानिफ्राय, दुखु आरो गिथावनिफ्राय, दाहारनि बोजानिफ्राय आरो सुबुंफोरनि नारसिन्नायनिफ्राय रैखा खालामनो नागिरो।", "दुखु, जिंगा, दाहारनि बोसो आरो गोसोआरि दुखुनि समाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोबां समावनो बे दुआखौ खालामो-दुखु, आलसिया आरो दाहारनि जिंगानिफ्राय रैखा।"),
        "dua_sayyidul_istighfar" to DuaText("सैयद अल-इस्तिघफार (क्षमा खालामनायनि गाहाय)", "ऐ अल्लाह, नों आंनि इसोर, नोंनि अनगा रावबो सिबिजानो हाथाव नङा। नों आंखौ सोरजिदों आरो आं नोंनि बान्दा, आरो आं नोंनि गोरोबथि आरो होनांखौ मानिना दं। आं जाय गाज्रि खामानि मावदोंमोन बेनिफ्राय आं नोंखौ आश्रय लायो। आं आंनि सायाव नोंनि अननायखौ गनायो आरो आं आंनि पापखौ गनायो, बेनिखायनो आंखौ क्षमा खालाम, मानोना नोंनि अनगायै रावबो पापखौ क्षमा खालामाखै।", "फुं आरो बेलासिम-पैगम्बर सल्लल्लाहु अलैहि वस्लमजों फोरोंजानाय उनदाहा खालामनायनि साबसिन दुआ।", "जाय बेलासियाव बेखौ रोखा महरै बुङो आरो बै हराव थैयो बियो सोरगोआव हाबगोन; फुंआव बुंब्ला बे एखे बाथ्रा बाहाय जायो।"),
        "dua_parents" to DuaText("बिमा-बिफानि थाखाय आरज गाबनाय।", "आंनि इसोर, बिसोर सानैखौ अननाय हो जेरै बिसोर आंखौ उन खांहोदोंमोन जेब्ला आं फिसामोन।", "सासेनि बिमा-बिफानि थाखाय मोनसे कुरानिक दुआ-उन्दै समाव बिसोरनि जोथोननि बदलै।", "अल्लाहआ गावनो जोंनि बिमा-बिफानि थाखाय बे दुआ बानायनो बिथोन होदोंमोन।"),
        "dua_entering_mosque" to DuaText("मस्जिदआव हाबना।", "ऐ अल्लाह, आंनि थाखाय नोंनि अननायनि दरजाखौ खेव।", "जेब्ला आगदा आथिंजों मस्जिदआव आगान होयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा मस्जिदआव हाबनो थाखाय बे दुआखौ फोरोंदोंमोन।"),
        "dua_morning_asbahna" to DuaText("फुंनि गोसोखांथि।", "जों फुंआव हाबदोंमोन आरो गासै रायजोआ अल्लानि फुंआव हाबदोंमोन। गासिबो बाख्नायनाया अल्लाहनि। अल्लाहनि अनगा रावबो बाख्नायजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनि बाख्नायनाया आरो बिथांनि बाख्नायनाया, आरो बिथाङा गासैबो जिनिसफोरनि सायाव गोहो गोनां।", "फुंआव मोनसे सुन्नत दुआ फरायदोंमोन।", "बे साना अल्लाहनि जारखुंथाय आरो बिथांनि एकथिखौ रोखा खालामनानै जागायजेनो।"),
        "dua_evening_amsayna" to DuaText("बेलासनि गोसोखांथि।", "जों बेलासियाव हाबफैदोंमोन आरो गासै रायजोआ अल्लानि बेलासियाव हाबदोंमोन। गासिबो बाख्नायनाया अल्लाहनि। अल्लाहनि अनगा रावबो बाख्नायजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनि बाख्नायनाया रायजो आरो बिथांनि बाख्नायनाया आरो बिथाङा गासैबो जिनिसनि सायाव गोहो गोनां।", "बेलासियाव मोनसे सुन्नत दुआ फरायदोंमोन।", "हरआ अल्लाहनि जारखुंथाय आरो बिथांनि एकथिखौ रोखा खालामनानै जागायजेनो।"),
        "dua_bismillah_la_yadurru" to DuaText("गासैबो खहाफोरनिफ्राय रैखा।", "अल्लाहनि मुंजों, जायनि मुंजों बुहुमाव एबा सोरगोआव जेबो खहा खालामनो हाया, आरो बिथाङा खोनानाय, मिन्थिग्रा।", "सानसेखालि फुं आरो बेलासियाव खेबथाम।", "जाय बेखौ फुंनि आरो बेलासियाव खेबथाम बुङो, बिखौ जेबो खहा खालामै।"),
        "dua_raditu_billahi" to DuaText("इसोर महरै अल्लाहजों गोजोन।", "आं आंनि इसोरनि महरै अल्लाहजों, इस्लामखौ आंनि धोरोम महरै आरो मुहम्मद सलिह आलीआ आंनि पैगंबरनि महरै गोजोनदों।", "खेबथाम फुं आरो बेलासियाव।", "बे अल्लाहनि सायाव मोनसे मोन्थाइ जायो दि बियो फिनाय सानाव बिखौ गोजोन होयो।"),
        "dua_hasbiyallah" to DuaText("हसबियल्लाह (अल्लाहानो थोजासे)", "आंनि थाखाय अल्लाहानो थोजासे; बिनि अनगा रावबो इसोर गैया। आं बिनि सायावनो फोथायो, आरो बियो गोहोगोरा राजउलाफादनि इसोर।", "स्नि खेब फुं आरो बेलासियाव।", "कुराननि मोनसे आय'द; बे मुलुग आरो उननि जिंगानि बेरेखायै अल्लाहानो थोजासे।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुभानअल्लाही वा बिहमदीही", "अल्लाहनो बाख्नायनाय आरो गासिबो बाख्नायनाया बिथांनि।", "सानसेयाव सेजौ खेब।", "जाय सानसेयाव जौ खेब बेखौ बुङो, बिनि पापफोरा लैथोनि फेना बायदिब्लाबो बेखौ माफ खालामनाय जायो।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वाहदहू", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो दं आरो बिथांनिनो बाख्नायनायनाय आरो बिथाङा गासैबो जिनिसनि सायाव गोहो दं।", "सानसेयाव सेजौ खेब बेखौ बुंनाया मोनसे गेदेर गुन।", "जि बान्दाफोरखौ उदां खालामनायनि बान्था, रोजा मोजां खामानि लिरनाय, रोजा पापफोरखौ फोजोबस्रांनाय आरो बेलासिम शयताननिफ्राय रैखा खालामनाय।"),
        "dua_leaving_mosque" to DuaText("मस्जिदखौ नागारनाय।", "ऐ अल्लाह, आं नोंखौ नोंनि अनथोबखौ सोङो।", "जेब्ला मस्जिदनिफ्राय आगसि आथिंजों ओंखारबोयो।", "मस्जिदनिफ्राय ओंखारबोयोब्ला अल्लाहनि अनथोब आरो राहा नागिरना ला।"),
        "dua_after_adhan" to DuaText("अधाननि उनाव", "ऐ अल्लाह, बे आबुं लिंहरनाय आरो गायसनजानो गोनां आरजखौ इसोर, मुहम्मद सल्लल्लाह वसीलाह आरो गुनखौ हो आरो बिखौ बै बाख्नायजानाय थाथायाव ला जाय नों बिखौ बावसोमबाय।", "अधानआ आबुं जानायनि उनाव।", "जाय बेबादि बुंगोन, बिखौ बिजिरनायनि सानाव पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मदद होनाय जागोन।"),
        "dua_after_salah_istighfar" to DuaText("फरद सालाहनि उनाव", "आं अल्लाहनिफ्राय (खेबथाम) क्षमा नागिरो। ऐ अल्लाह, नों सालाम आरो नोंनिफ्राय गोजोन। हे गेदेमा आरो मान मोनग्रानि, नोंनो बरनाय।", "सालामनि उनावनो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा मोनफ्रोमबो गोनांथार आरज गाबनायनि उनाव बेखौ फरायदोंमोन।"),
        "dua_after_salah_help_dhikr" to DuaText("नोंखौ गोसोआव लाखिनायनि थाखाय आंनो मदद खालाम।", "ऐ अल्लाह, नोंखौ गोसोखांनो, नोंखौ बाखनायनो आरो नोंखौ साबसिन रोखोमै सिबिनो थाखाय आंखौ मदद खालाम।", "मोनफ्रोमबो आरज गाबनायनि उनाव-पैगम्बर सल्लल्लाहु अलैहि वस्लमा मुआद (रा.) खौ बेखौ बुंनो बोसोन होदोंमोन।", "पैगंबर सल्लल्लाहु अलैहि वस्लमनि मोनसे जुनिया बोसोन-सिबिथायाव साबसिन आरो दिदोमथि।"),
        "dua_ayatul_kursi" to DuaText("सालाहनि उनाव आयत अल-कुर्सी।", "अल्लाह-बिनि अनगा रावबो इसोर गैया, जाय थांना थायो, गासैनिबो खांग्रा। उनदुनो आरो उनदुनोबो नङा। आकाशफोराव आरो बुहुमाव जायबो दं, बियो बिनिनो। बिथांनि गनायथि गैयाब्ला आरो सोर बिथांनि फारसे बोसोन होनो हायो? बिथाङा मिन्थिना थायो दि बिसोरनि सिगाङाव आरो उनाव मा दं, आरो बिथाङा जायखौ गोसो होयो बिनि अनगायै बिथांनि गियाननि जेबो बाहागोखौ बिसोर खोबया। बिथांनि कुरसिया आकाश आरो बुहुमनि सायाव गोसारो, आरो बिसोरखौ रैखा खालामनाया बिथांखौ मेंनाय नङा। बिथाङा गोजौसिन, गेदेरसिन।", "मोनफ्रोमबो गोनांथार आरज गाबनायनि उनाव आरो उनदुनो सिगां।", "थैनायनि अनगा जेबो गैया, जाय मोनफ्रोमबो गोनांथार आरज गाबनायनि उनाव बेखौ फोरोङो आरो सोरगोनि गेजेराव; उन्दुनायनि सिगां फोरोङो, बेयो फुंसिम रैखाथि लाबोयो।"),
        "dua_before_sleep" to DuaText("उन्दुनायनि सिगां।", "ऐ अल्लाह, नोंनि मुंजों आं थैयो (उनदुनो) आरो आं जिउ खांो (जागो)।", "उनदुङाव उनदुनो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा उनदुनो सिगां बेखौ फरायदोंमोन।"),
        "dua_sleep_tasbeeh" to DuaText("उनदुनो सिगां तसबीह-ए-फातिमा", "अल्लाहनो महिमामाया (33), गासिबो बाख्नायनाया अल्लाहनि थाखाय (33), अल्लाहआ बयनिख्रुइबो देरसिन (34)।", "उनदुनाय सिगां-पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ फातिमा आरो आली (रा.) नो फोरोंदोंमोन।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुंदोंमोन दि बे नोंनि थाखाय सासे बान्दानिफ्राय साबसिन।"),
        "dua_sleep_qina_adhab" to DuaText("साजानिफ्राय रैखा।", "ऐ अल्लाह, जिस सानाव नों नोंनि बान्दाफोरखौ फिन जोनोम होयो, बे सानाव नों आंनो नोंनि साजानिफ्राय रैखा खालाम।", "थाम खेब, आगदा आखायखौ गालानि गाहायाव दोन।", "उनदुनो थैनायनि गोसोखांथि आरो उननि थाखाय थियारि खालामनायाव सोलायहोयो।"),
        "dua_bad_dream" to DuaText("मोनसे गाज्रि सिमांनि उनाव", "आं शापित शयताननिफ्राय अल्लाहनि शरण लायो।", "मोनसे गाज्रि सिमांनि उनावः आगसिथिं एसे खेबथाम गोरान थुख्राइ, बेनि उनाव गुबुन फारसेथिं गिदिं।", "गाज्रि सिमांआ नोंखौ खहा खालामाखै; बेनि बागै रावबो खोन्थानो नाङा।"),
        "dua_yunus" to DuaText("पैगम्बर यूनुस (ए. एस.) नि दुआ।", "नोंनि अनगा रावबो इसोर गैया। नोंनो गोग्गानाय। थारैनो, आं गोरोनथि खालामग्राफोरनि गेजेराव दं।", "तिमिनि उदैयाव पैगंबर यूनुस (एएस) नि दुआ-मोनफ्रोमबो गोब्राबथिनि थाखाय।", "जायखिजाया मुस्लिम जाय जायखिजाया बाथ्राखौ लानानै बे दुआ खालामो, अल्लाहआ बिखौ फिन होयो।"),
        "dua_karb" to DuaText("दुख'ति समाव दुआ (कार्ब)", "सोरनावबो फुजिजानायनि मोन्थाइ गैया, गोहोगोरा, सहायग्रा अल्लाहनि अनगा। सोरनावबो फुजिजानायनि मोन्थाइ गैया, गोहोगोरा राजउलाफादनि इसोर अल्लाहनि अनगा। सोरनावबो फुजिजानायनि मोन्थाइ गैया, आकाशनि इसोर, बुहुमनि इसोर आरो गोजौ राजउलाफादनि इसोर अल्लाहनि अनगा।", "गोब्राब दुखु आरो गोब्राब समाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा दुखु समाव बेखौ फरायदोंमोन।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हयू या कयुम", "ऐ अराय जिउगोनां, ऐ गासिबोनि खांग्रा! नोंनि अननायजों आं मदद नागिरो।", "जेब्ला मोनसे बाथ्राया जोबोद गिलिर जायो।", "जेब्लाबो पैगंबरखौ माबा खायदा दुखु होयो, अब्ला बिथाङा बे बाथ्राखौ बुङोमोन।"),
        "dua_hasbunallah" to DuaText("हसबुनाल्लाहु वा निमाल वकील", "अल्लाहआ जोंनि थाखाय थोजासे आरो बिथाङा साबसिन सामलायगिरि।", "जेब्ला सोरबा सुथुरखौ गियो एबा जोबोद खैफोदनि मोगामोगि जायो।", "पैगम्बर इब्राहिम (आ. स.) आ अराव गारनायाव बेखौ बुंदोंमोन आरो पैगम्बर सल्लल्लाहु अलैहि वस्लमा खैफोदनि समाव बेखौ बुंदोंमोन।"),
        "dua_entering_home" to DuaText("न'आव हाबफैनाय।", "अल्लाहनि मुंजों।", "न'आव हाबनायाव अल्लाहनि मुं बुं आरो सलामजों बरनाय।", "जेब्ला अल्लाहखौ हाबनायाव आरो जानाय-लोंनाय समाव गोसोखांनाय जायो, अब्ला शयताना बुङोः बेवहाय थानो थाखाय जेबो जायगा गैया आरो नोंनि थाखाय जानाय-लोंनायनिबो जेबो जायगा गैया।"),
        "dua_travel" to DuaText("दावबायनायनि थाखाय दुआ (गाखोनाय)", "जाय जोंनि सिङाव बेखौ दोनदोंमोन, आरो जों गावनो बेखौ खालामनो हायामोन, आरो थारैनो जों जोंनि इसोरनि खाथियाव फैफिनो।", "गारिआव जिरायना आरो थाम खेब अल्लाहू आकबर बुंनायनि उनाव।", "सुन्नाह दावबायनाय दुआ-रैखाथि आरो बोर होनायनि थाखाय।"),
        "dua_entering_market" to DuaText("हाथाइनि जायगायाव हाबना।", "अल्लाहनि अनगा रावबो सिबिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो आरो बिथांनिनो बाख्नायनायनाय। बिथाङा जिउ होयो आरो थैहोयो, आरो बिथाङा अराय जिउगोनां आरो माब्लाबाबो थैयाखै। बिथांनि आखायआव गासैबो मोजां आरो बिथाङा गासैबो जिनिसनि सायाव गोहो गोनां।", "हाथाइआव हाबनायाव।", "हादिसा बेनि थाखाय मोनसे गिदिर बान्था (लाखसे मोजां खामानि) खौ मुंख'यो।"),
        "dua_adam_forgiveness" to DuaText("पैगम्बर आदम (आ. स.) नि दुआ।", "जोंनि इसोर, जों गाव-गावनि सायाव अनागारि खालामदों, आरो जुदि नों आंखौ बावगाराखै आरो जोंनि सायाव अननाय गैया, अब्ला जों थारैनो खहा जानायफोरनि गेजेराव जागोन।", "आदम आरो हाववा (ए. एस.) नि उनदाहा।", "सुबुंथिनि गिबि उनदाहा-अल्लाहआ बेखौ नाजावो।"),
        "dua_abu_bakr" to DuaText("दुआआ आबु बकर (रा.) नो फोरोंदोंमोन।", "ऐ अल्लाह, आं गावखौ जोबोद अनागारि खालामदों, आरो नोंनि अनगा रावबो अनागारखौ क्षमा खालामाखै, बेनिखायनो आंनो गावनिफ्रायनो अनागार हो आरो आंनो अननाय हो। थारैनो, नोंनो अनागारगिरि, अनजाथाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा आबु बकर अस-सिद्दीक (र.) नो आरज गाबनायाव (ताशाहहुदनि उनाव) बुंनो फोरोंदोंमोन।", "आरज गाबनायनि जोबनायथिं मोनसे सुन्नत दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("सानफ्रोमबो इस्तिघफार", "आं अल्लाहनिफ्राय क्षमा आरजियो आरो उनदाहा जानानै बिथांनि फारसे गिदिंबो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा सानसेयाव स्निजि खेबनिफ्राय बांसिन क्षमा नागिरदोंमोन।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुङोः आं अल्लाहनिफ्राय क्षमा आरजियो आरो सानसेयाव स्निजि खेबनिफ्राय बांसिन उनदाहा खालामो।"),
        "dua_laylatul_qadr" to DuaText("लैलात अल-कदरनि थाखाय दुआ।", "ऐ अल्लाह, नों जोबोरैनो बावगारग्रा आरो नों बावगारनो मोजां मोनो, बेनिखायनो आंखौ बावगार।", "लैलात अल-कदरनि थाखाय आयशा (आर. ए.) नो फोरोंनाय जादोंमोन।", "रमजाननि जोबथा हरफोर आरो लैलात अल-कदरनि थाखाय मोनसे जुनिया दुआ।"),
        "dua_family_coolness" to DuaText("मेगननि गुसु जानाय (बिसि आरो गथ'सा)", "जोंनि इसोर, जोंनि बिसिफोर आरो जोंनि फिसाफोरनिफ्राय जोंनि मेगननि गुसुथिखौ हो, आरो जोंफोरखौ गोथारफोरनि दैदेनगिरि खालाम।", "सासे गोथार बिसि आरो गथ'फोरनि थाखाय मोनसे कुरान दुआ।", "न'आव गोजोन आरो गोथार गथ'फोरनि थाखाय।"),
        "dua_righteous_children" to DuaText("गोथार फिसाफोरनि थाखाय", "आंनि इसोर, नोंनिफ्राय आंनो गोथार फिसाफोर हो। थारैनो नों आरजखौ खोनानाय।", "पैगंबर ज़कारिया (ए. एस.) नि दुआ।", "गथ'फोरखौ नागिरग्राफोरनि थाखाय मोनसे कुरान दुआ।"),
        "dua_ibrahim_prayer_family" to DuaText("आरज गाबनायनि गायसनगिरिफोर।", "आंनि इसोर, आंनो आरज गाबनायनि आरो आंनि फोलेरनिफ्राय गायसनग्रा खालाम। जोंनि इसोर, आंनि आरजखौ आजाव। जोंनि इसोर, आंनो, आंनि बिमा-बिफा आरो फोथायगिरिफोरखौ सानफिथि थि जानाय सानाव क्षमा खालाम।", "पैगंबर इब्राहिम (ए. एस.) नि दुआआ गावनि आरो गावनि फोलेरफोरनि थाखाय।", "सरासनस्रायै आरज गाबनायनि जोबनायाव फरायजायो।"),
        "dua_newlywed" to DuaText("गोदान जुलिखौ बाख्नायनायनाय।", "अल्लाहआ नोंखौ बोर होहो, नोंखौ बोर हो आरो नोंखौ सानैखौबो मोजांनि थाखाय ज'खालाम।", "जेब्ला सोरबा सासेखौ बिनि हाबानि थाखाय बाख्नायो।", "सुन्नाआ जुलि जानायनि थाखाय बाख्नायो।"),
        "dua_before_eating" to DuaText("जानाय सिगां।", "अल्लाहनि मुंजों। (बावगारनाय जायोब्लाः) अल्लाहनि मुंजों, बिनि जागायनायाव आरो जोबनायाव।", "जानाय सिगां। जुदि नों बावगारो, अब्ला बेखौ एसेसो बुं।", "बिस्मिल्लाह बुंनाया शयतानखौ जामुंखौ रानलायनायनिफ्राय होबथायो।"),
        "dua_after_eating" to DuaText("जानाय-लोंनाय उनाव।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय जाय आंनो बेखौ जाहैयो आरो आंनि फारसेनिफ्राय जेबो गोहो एबा गोहो गैयालासेनो बेखौ होयो।", "जानाय-लोंनायनि उनाव।", "जाय बेखौ बुङो बिनि सिगांनि पापफोरा क्षमा खालामजायो।"),
        "dua_host" to DuaText("होस्टनि थाखाय", "ऐ अल्लाह, नों बिसोरखौ जाय होदों, बेयाव बिसोरखौ बोर हो, बिसोरखौ क्षमा खालाम आरो बिसोरखौ अननाय।", "आलासिनि थाखाय, सोरबा सासेनि न'आव जानाय-लोंनाय उनाव।", "होस्टखौ सुन्नाहनि राहाजों बाखनायनाय।"),
    )
}
